#!/usr/bin/env python3
"""
Round 189o (culprits-tiles-more), 8 October 2026.

- meat_dairy_methane.py (new): the 15 meat and dairy companies of Emissions
  Impossible: Methane Edition (IATP and Changing Markets Foundation, 2022),
  from the report's dataset workbook (methane/emissions_impossible/
  dataset.json, every sheet as the workbook holds it), each at its Wikidata
  headquarters. Writes methane/meat_dairy.places.geojson, .boxes.json and
  .build.json.
- medical_culprits.py: Alpha Therapeutic Corporation placed at the address
  on its 1987 letterhead (Infected Blood Inquiry document KDUD0000001).

Written only if it differs. Run from the repository root (apply-patch does).
"""
import base64, pathlib, sys

FILES = {'scripts/meat_dairy_methane.py': '', 'scripts/medical_culprits.py': '', 'methane/emissions_impossible/dataset.json': ''}

def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("round189o_tiles: run from the culprits-tiles-more repository root")
    changed = 0
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        p = pathlib.Path(path)
        if p.exists() and p.read_bytes() == data:
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(data)
        changed += 1
        print(f"round189o_tiles: wrote {path}")
    if not changed:
        print("round189o_tiles: already applied")


if __name__ == "__main__":
    main()
